/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.metric.MetricPoint;
import net.civeira.phylax.testing.sql.H2Database;

/** The telemetry stored on a sql database (here h2), with its own tables. */
class SqlTelemetryStoreH2UnitTest {
  private static final long DAY = 86_400_000L;
  private SqlTelemetryStore store;
  private long now;

  @BeforeEach
  void setUp() {
    store = new SqlTelemetryStore(new H2Database().dataSource());
    now = System.currentTimeMillis();
  }

  private ObsLog log(long ts, String src, String level, String msg, String traceId) {
    return new ObsLog(ts, src, level, "logger", msg, traceId, "span", null, Map.of("k", "v"), "1.0",
        "prod");
  }

  private ObsSpan span(long ts, String src, String traceId, String spanId, String parent,
      String status) {
    return new ObsSpan(ts, src, traceId, spanId, parent, "GET /x", "SERVER", 12.5, status, Map.of(),
        "1.0", "prod");
  }

  private TelemetryQuery.TelemetryQueryBuilder all() {
    return TelemetryQuery.builder().from(now - DAY).to(now + DAY);
  }

  @Test
  @DisplayName("The logs are stored and filtered by source, level, text and trace")
  void logs() {
    store.appendLogs(List.of(log(now - 3, "api", "INFO", "started", "t1"),
        log(now - 2, "api", "ERROR", "payment 50% failed", "t2"),
        log(now - 1, "web", "WARN", "slow page", "t3")));

    List<ObsLog> found = store.logs(all().build());
    Assertions.assertEquals(3, found.size());
    Assertions.assertEquals("slow page", found.get(0).msg(), "The newest first");
    Assertions.assertEquals(2, store.logs(all().sources(Set.of("api")).build()).size());
    Assertions.assertEquals(2, store.logs(all().minLevel(Optional.of("warn")).build()).size());
    Assertions.assertEquals(1, store.logs(all().text(Optional.of("50%")).build()).size(),
        "The text is searched with the like wildcards escaped");
    Assertions.assertEquals(1, store.logs(all().traceId(Optional.of("t2")).build()).size());
    Assertions.assertEquals(1, store.logs(all().limit(1).build()).size());
    Assertions.assertTrue(
        store.logs(TelemetryQuery.builder().from(now + DAY).to(now + 2 * DAY).build()).isEmpty(),
        "Out of the time window");
  }

  @Test
  @DisplayName("The spans are stored and read by trace and by errors")
  void spans() {
    store.appendSpans(List.of(span(now - 2, "api", "t1", "s1", null, "OK"),
        span(now - 1, "api", "t1", "s2", "s1", "ERROR"), span(now, "web", "t2", "s3", null, "OK")));

    Assertions.assertEquals(3, store.spans(all().build()).size());
    Assertions.assertEquals(2, store.trace("t1", now - DAY, now + DAY).size());
    Assertions.assertEquals(3, store.traces(Set.of("t1", "t2"), now - DAY, now + DAY).size());
    List<ObsSpan> errors = store.spans(all().errors(true).build());
    Assertions.assertTrue(errors.stream().allMatch(ObsSpan::isError) && !errors.isEmpty(),
        "Only the failed spans");
  }

  @Test
  @DisplayName("The metric points are read by step and source in time order")
  void points() {
    store.appendPoints(List.of(
        new MetricPoint(now - 60_000, 60_000, "api", "/x", "GET", 3, 1, 30.0, new long[] {1, 2}),
        new MetricPoint(now, 60_000, "api", "/x", "GET", 2, 0, 10.0, new long[] {2, 0}),
        new MetricPoint(now, 3_600_000, "api", "/x", "GET", 5, 1, 40.0, new long[] {3, 2})));

    List<MetricPoint> minutes = store.points(now - DAY, now + DAY, 60_000, Set.of("api"));
    Assertions.assertEquals(2, minutes.size());
    Assertions.assertTrue(minutes.get(0).ts() <= minutes.get(1).ts());
    Assertions.assertEquals(1, store.points(now - DAY, now + DAY, 3_600_000, Set.of()).size());
    Assertions.assertTrue(store.points(now - DAY, now + DAY, 60_000, Set.of("web")).isEmpty());
  }

  @Test
  @DisplayName("The purge removes the data older than its retention, also by source")
  void purge() {
    store.appendLogs(List.of(log(now - 30 * DAY, "api", "INFO", "old", null),
        log(now - 5 * DAY, "noisy", "INFO", "noise", null),
        log(now - 5 * DAY, "api", "INFO", "kept", null)));
    store.appendSpans(List.of(span(now - 30 * DAY, "api", "t1", "s1", null, "OK")));

    store.purge(new RetentionPolicy(14, 7, 0, 15, 400).withSources(Map.of("noisy", 3)));

    List<ObsLog> left = store.logs(TelemetryQuery.builder().from(now - 60 * DAY).to(now).build());
    Assertions.assertEquals(List.of("kept"), left.stream().map(ObsLog::msg).toList());
    Assertions.assertTrue(
        store.spans(TelemetryQuery.builder().from(now - 60 * DAY).to(now).build()).isEmpty());
    Assertions.assertEquals(0, store.sizeBytes());
  }
}
